inline static uint16_t calc_1byte_mcuboot_crc(const uint16_t crc, const uint8_t byte)
{
    return (crc << 8) ^ crc_table[(crc >> 8) ^ byte];
}

static void calculate_mcuboot_CRC(uint16_t *crc, const void *data, size_t length)
{
	const uint8_t *p = (const uint8_t *)data;
	uint16_t c = *crc;
	for (; length > 0; length--)
	{
		c = calc_1byte_mcuboot_crc(c, *p);
		p++;
	}
	*crc = c;
}


