#define MCUBOOT_PTYPE_ACK		0xA1
#define MCUBOOT_PTYPE_NAK		0xA2
#define MCUBOOT_PTYPE_ABORT		0xA3
#define MCUBOOT_PTYPE_COMMAND	0xA4
#define MCUBOOT_PTYPE_DATA		0xA5
#define MCUBOOT_PTYPE_PING		0xA6
#define MCUBOOT_PTYPE_PONG		0xA7



void nxp_mcuboot_send_ack(void)
{
	const uint8_t frame[] = { NXP_MCUBOOT_STARTBYTE, MCUBOOT_PTYPE_ACK };
	NXP_OTA_UART_WRITE(frame, sizeof(frame));
}


static void nxp_mcuboot_send_nak(void)
{
	const uint8_t frame[] = { NXP_MCUBOOT_STARTBYTE, MCUBOOT_PTYPE_NAK };
	NXP_OTA_UART_WRITE(frame, sizeof(frame));
}


static void nxp_mcuboot_send_frame(uint8_t ptype, const void *payload, size_t length)
{
	struct {
		uint8_t start_byte;
		uint8_t type;
		uint16_t length;
		uint16_t crc;
	} frame;

	_Static_assert(sizeof(frame) == 6);

    frame.start_byte = NXP_MCUBOOT_STARTBYTE;
    frame.type = ptype;
    frame.length = length;
    frame.crc = MCUBOOT_CRC_INIT_VAL;
    calculate_mcuboot_CRC(&frame.crc, &frame, 4);	//exclude CRC field
    if(length > 0) calculate_mcuboot_CRC(&frame.crc, payload, length);

    NXP_OTA_UART_WRITE(&frame, sizeof(frame));
    if(length > 0) NXP_OTA_UART_WRITE(payload, length);
}


static void nxp_mcuboot_send_command_packet(const void *data, size_t length)
{
	nxp_mcuboot_send_frame(MCUBOOT_PTYPE_COMMAND, data, length);
}


void nxp_mcuboot_send_data_packet(const void *data, size_t length)
{
	nxp_mcuboot_send_frame(MCUBOOT_PTYPE_DATA, data, length);
}



